from mk import *
from lib import fbd
STRICT["on"] = True

def panel(g, ox, oy, title, vecs, extra=None):
    s = 16
    for i in range(13): g.line(ox + i * s, oy, ox + i * s, oy + 12 * s, stroke="var(--d-hatch)", width=0.7)
    for j in range(13): g.line(ox, oy + j * s, ox + 12 * s, oy + j * s, stroke="var(--d-hatch)", width=0.7)
    g.rect(ox, oy, 12 * s, 12 * s, fill="none", width=1.2)
    for (px, py, dx, dy, lab) in vecs:
        x0, y0 = ox + px * s, oy + (12 - py) * s
        g.circle(x0, y0, 4, fill="var(--d-label)"); g.text(x0 + 7, y0 + 4, lab, cls="dim", anchor="start")
        g.arrow(x0, y0, x0 + dx * s, y0 - dy * s, None, width=1.8)
    if extra: extra(ox, oy, s)
    g.heb(ox + 6 * s, oy + 12 * s + 20, title)

def fig():
    g = Fig(560, 470, "ארבעה תרשימים על רשת שבה כל משבצת היא 1 מטר לשנייה. תרשים א: כדור m במהירות (6-, 8-) וכדור 2m במהירות (0, 4). תרשים ב: m במהירות (6-, 8) ו-2m במהירות (0, 4). תרשים ג: m במהירות (6, 8), 2m במהירות (0, 4-), והקרון 3 מטר לשנייה שמאלה. תרשים ד: m במהירות (8, 6) ו-2m במהירות (4-, 0)")
    panel(g, 300, 10, "תרשים א", [(10, 8, -6, -8, "m"), (1, 1, 0, 4, "2m")])
    panel(g, 40, 10, "תרשים ב", [(6, 0, -6, 8, "m"), (2, 7, 0, 4, "2m")])
    panel(g, 300, 245, "תרשים ד", [(1, 2, 8, 6, "m"), (9, 11, -4, 0, "2m")])
    panel(g, 40, 245, "תרשים ג", [(2, 2, 6, 8, "m"), (9, 10, 0, -4, "2m")], extra=lambda ox, oy, s: (g.arrow(ox - 4, oy + 4 * s, ox - 34, oy + 4 * s, None), g.text(ox - 34, oy + 4 * s + 18, "3 m/s", cls="dim", anchor="start")))
    return g

